def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Immediate state
    last_me, last_op = history[-1]

    # Counts
    op_def = 0
    my_def = 0
    for a, b in history:
        if b == 'D':
            op_def += 1
        if a == 'D':
            my_def += 1

    # Early game: cooperate, but retaliate briefly for early defection
    if n < 5:
        if last_op == 'D':
            return 'D'
        return 'C'

    # Detect current run lengths
    op_c_run = 0
    for a, b in reversed(history):
        if b == 'C':
            op_c_run += 1
        else:
            break

    op_d_run = 0
    for a, b in reversed(history):
        if b == 'D':
            op_d_run += 1
        else:
            break

    my_d_run = 0
    for a, b in reversed(history):
        if a == 'D':
            my_d_run += 1
        else:
            break

    # Recent cooperation rates
    w = 10 if n >= 10 else n
    recent_op_c = 0
    recent_my_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_op_c += 1
        if history[i][0] == 'C':
            recent_my_c += 1
    recent_op_rate = recent_op_c / w
    total_op_rate = (n - op_def) / n

    # If opponent has been almost perfectly cooperative, cooperate and exploit only in final rounds.
    if op_def == 0:
        if n >= 97:
            return 'D'
        return 'C'

    # Late-game phase
    if n >= 95:
        # If opponent is very cooperative overall, defect for value
        if total_op_rate >= 0.9:
            return 'D'
        # If opponent recently cooperative, defect; if defecting, defect back
        if last_op == 'C':
            if recent_op_rate >= 0.5:
                return 'D'
            return 'C'
        return 'D'

    # If opponent is mostly cooperative, avoid unnecessary defection.
    if op_def <= 2 and recent_op_rate >= 0.7:
        # Retaliate once if just defected
        if last_op == 'D':
            return 'D'
        return 'C'

    # If opponent recently very cooperative after rough start, cooperate.
    if recent_op_rate >= 0.8:
        if last_op == 'D':
            return 'D'
        return 'C'

    # If opponent is mostly defecting, defect hard but occasionally test.
    if total_op_rate <= 0.3 or recent_op_rate <= 0.2:
        if op_d_run >= 4:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if last_op == 'D':
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        # Opponent cooperated last round despite bad history: reciprocate cautiously.
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Moderate opponent: tit-for-tat with limited forgiveness.
    if last_op == 'D':
        # If opponent just broke a long cooperative run, retaliate.
        if op_d_run == 1 and op_c_run >= 3:
            return 'D'
        # If we have been defecting repeatedly, try to restore cooperation.
        if my_d_run >= 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Otherwise punish but allow early return to cooperation.
        if op_d_run >= 3:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # Avoid endless punishment if we were the aggressor.
    if my_d_run >= 2:
        return 'C'

    # If opponent's recent rate is solid, cooperate.
    if recent_op_rate >= 0.5:
        return 'C'

    # If opponent is only moderately cooperative, alternate cooperation and probing.
    if op_def * 2 < n and recent_op_rate >= 0.4:
        if rng.random() < 0.1:
            return 'D'
        return 'C'

    # Default cautious cooperation.
    if rng.random() < 0.2:
        return 'D'
    return 'C'
